        "description": "8月5日，河南带薪休假新政对外公布。不同于多地侧重倡议引导，河南强化多部门协同，推动落实职工带薪错峰休假，重点强调单位主要负责人为第一责任人，领导干部要带头休假。中央财经大学法学院教授沈建峰表示，该举措可破除职工“不敢休”的职场顾虑，发挥关键少数示范带动效应，整体方案具备很强的可推广借鉴价值。",
